[{"order":1,"type":"heading","text":"Enterprise Test Reporting and Logging in Selenium"},{"order":2,"type":"paragraph","text":"Robust logging and advanced reporting are crucial for maintaining scalable Selenium automation frameworks. This tutorial explores the integration of Log4j2 for logging, Extent Reports for HTML reporting, and Allure Reporting for comprehensive analytics."},{"order":3,"type":"subheading","text":"1. Setting Up Log4j2 for Advanced Logging"},{"order":4,"type":"paragraph","text":"Log4j2 provides efficient logging capabilities to track test execution flows and debug failures. First, add the Log4j2 dependencies to your pom.xml file."},{"order":5,"type":"code","text":"<dependency>
    <groupId>org.apache.logging.log4j</groupId>
    <artifactId>log4j-core</artifactId>
    <version>2.20.0</version>
</dependency>
<dependency>
    <groupId>org.apache.logging.log4j</groupId>
    <artifactId>log4j-api</artifactId>
    <version>2.20.0</version>
</dependency>"},{"order":6,"type":"paragraph","text":"Next, create a log4j2.xml configuration file under your src/test/resources directory to define logging levels and appenders."},{"order":7,"type":"code","text":"<?xml version="1.0" encoding="UTF-8"?>
<Configuration status="WARN">
    <Appenders>
        <Console name="Console" target="SYSTEM_OUT">
            <PatternLayout pattern="%d{HH:mm:ss.SSS} [%t] %-5level %logger{36} - %msg%n"/>
        </Console>
        <File name="FileLogger" fileName="logs/automation.log">
            <PatternLayout pattern="%d{yyyy-MM-dd HH:mm:ss} [%p] %C{1} - %msg%n"/>
        </File>
    </Appenders>
    <Loggers>
        <Root level="info">
            <AppenderRef ref="Console"/>
            <AppenderRef ref="FileLogger"/>
        </Root>
    </Loggers>
</Configuration>"},{"order":8,"type":"subheading","text":"2. Integrating Extent Reports"},{"order":9,"type":"paragraph","text":"Extent Reports produce interactive and visually appealing HTML reports. Add the ExtentReports dependency to your project."},{"order":10,"type":"code","text":"<dependency>
    <groupId>com.aventstack</groupId>
    <artifactId>extentreports</artifactId>
    <version>5.0.9</version>
</dependency>"},{"order":11,"type":"paragraph","text":"Create an ExtentManager utility class to handle report initialization and thread-safe test creation."},{"order":12,"type":"code","text":"public class ExtentManager {
    private static ExtentReports extent;
    private static ThreadLocal<ExtentTest> test = new ThreadLocal<>();

    public static ExtentReports createInstance() {
        ExtentSparkReporter reporter = new ExtentSparkReporter("reports/ExtentReport.html");
        reporter.config().setReportName("Automation Execution Report");
        reporter.config().setDocumentTitle("Test Results");

        extent = new ExtentReports();
        extent.attachReporter(reporter);
        return extent;
    }

    public static synchronized ExtentTest getTest() {
        return test.get();
    }

    public static synchronized void setTest(ExtentTest extentTest) {
        test.set(extentTest);
    }
}"},{"order":13,"type":"subheading","text":"3. Integrating Allure Reporting"},{"order":14,"type":"paragraph","text":"Allure provides rich web-based reporting with step-by-step execution traces, attachments, and historical analytics. Add the Allure TestNG and RestAssured/Core dependencies."},{"order":15,"type":"code","text":"<dependency>
    <groupId>io.qameta.allure</groupId>
    <artifactId>allure-testng</artifactId>
    <version>2.21.0</version>
</dependency>"},{"order":16,"type":"paragraph","text":"You can attach screenshots directly to Allure reports using listener classes and standard Allure attachments."},{"order":17,"type":"code","text":"public class AllureAttachments {
    @Attachment(value = "Page screenshot", type = "image/png")
    public static byte[] saveScreenshot(WebDriver driver) {
        return ((TakesScreenshot) driver).getScreenshotAs(OutputType.BYTES);
    }

    @Attachment(value = "{0}", type = "text/plain")
    public static String saveTextLog(String message) {
        return message;
    }
}"},{"order":18,"type":"subheading","text":"4. Combining Logging and Reporting in a Base Test"},{"order":19,"type":"paragraph","text":"Combine Log4j2, Extent Reports, and Allure in a TestNG base class to streamline logging and reporting during test execution."},{"order":20,"type":"code","text":"public class BaseTest {
    protected WebDriver driver;
    private static final Logger logger = LogManager.getLogger(BaseTest.class);
    private static ExtentReports extent = ExtentManager.createInstance();

    @BeforeMethod
    public void setUp(Method method) {
        logger.info("Starting test: " + method.getName());
        ExtentTest extentTest = extent.createTest(method.getName());
        ExtentManager.setTest(extentTest);

        driver = new ChromeDriver();
        driver.manage().window().maximize();
    }

    @AfterMethod
    public void tearDown(ITestResult result) {
        if (result.getStatus() == ITestResult.FAILURE) {
            logger.error("Test failed: " + result.getName());
            ExtentManager.getTest().fail(result.getThrowable());
            AllureAttachments.saveScreenshot(driver);
            AllureAttachments.saveTextLog("Test failed: " + result.getName());
        } else if (result.getStatus() == ITestResult.SUCCESS) {
            logger.info("Test passed: " + result.getName());
            ExtentManager.getTest().pass("Test Passed Successfully");
        }
        if (driver != null) {
            driver.quit();
        }
        extent.flush();
    }
}"},{"order":21,"type":"subheading","text":"Summary"},{"order":22,"bullet_point":"Log4j2 records detailed system actions to both console and files."},{"order":23,"bullet_point":"Extent Reports generates a neat, single-file HTML executive report."},{"order":24,"bullet_point":"Allure Reporting tracks complex test steps, environment metadata, and screenshot attachments seamlessly."}]
